import { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Plus, PanelLeft } from 'lucide-react'
import { useSidebar } from '@/contexts/SidebarContext'
import { CollectionHeader } from './CollectionHeader'

interface FilterOption {
  value: string
  label: string
  count?: number
}

interface EmptyStateConfig {
  icon: ReactNode
  title: string
  description: string
  noItemsTitle?: string
  noItemsDescription?: string
  showAddButton?: boolean
  addButtonText?: string
}

interface CollectionPageProps<TItem> {
  // Core data
  items: TItem[]
  filteredItems: TItem[]
  loading: boolean

  // Header configuration
  title: string
  subtitle?: string

  // Search and filtering
  searchTerm: string
  onSearchChange: (term: string) => void
  searchPlaceholder?: string

  // Primary filter (optional)
  primaryFilter?: {
    options: FilterOption[]
    selectedValue: string | null
    onSelectValue: (value: string | null) => void
    placeholder?: string
    allItemsLabel?: string
    totalItems?: number
    mobileFilterOptions?: FilterOption[]
  }


  // View mode support (optional)
  viewMode?: {
    current: string
    onChange: (mode: string) => void
    component: ReactNode
  }

  // Secondary controls (optional)
  secondaryControls?: ReactNode


  // Empty states
  emptyState: EmptyStateConfig

  // Item rendering
  renderItems: (items: TItem[], viewMode?: string) => ReactNode

  // Action handlers
  onAdd?: () => void

  // Modal slots
  renderModals?: () => ReactNode

  // Floating action button
  showFloatingActionButton?: boolean

  // Custom loading skeleton
  renderLoadingSkeleton?: () => ReactNode
}

export function CollectionPage<TItem>({
  items,
  filteredItems,
  loading,
  title,
  subtitle,
  searchTerm,
  onSearchChange,
  searchPlaceholder,
  primaryFilter,
  viewMode,
  secondaryControls,
  emptyState,
  renderItems,
  onAdd,
  renderModals,
  showFloatingActionButton = false,
  renderLoadingSkeleton
}: CollectionPageProps<TItem>) {
  const { toggleSidebar } = useSidebar()

  const hasNoItems = items.length === 0
  const hasNoFilteredItems = filteredItems.length === 0
  const isFiltered = searchTerm || primaryFilter?.selectedValue

  const defaultLoadingSkeleton = () => (
    <div className="space-y-4">
      {[...Array(5)].map((_, i) => (
        <Skeleton key={i} className="h-16 w-full" />
      ))}
    </div>
  )

  return (
    <div className="min-h-screen">
      <div className="">
        {/* Page Header */}
        <div className="px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
          <div className="flex items-start gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={toggleSidebar}
              className="hidden lg:flex mt-1 h-8 w-8 hover:bg-accent rounded-md flex-shrink-0"
              aria-label="Toggle sidebar"
            >
              <PanelLeft className="h-4 w-4" />
            </Button>
            <div className="flex-1">
              <h1 className="text-2xl sm:text-3xl font-bold tracking-tight">{title}</h1>
              {subtitle && (
                <p className="text-muted-foreground mt-1 text-sm sm:text-base">
                  {subtitle}
                </p>
              )}
            </div>
          </div>
        </div>

        {/* Collection Header */}
        <CollectionHeader
          searchTerm={searchTerm}
          onSearchChange={onSearchChange}
          searchPlaceholder={searchPlaceholder}
          primaryFilter={primaryFilter}
          secondaryControls={
            <>
              {viewMode && viewMode.component}
              {secondaryControls}
            </>
          }
          mobileFilterOptions={primaryFilter?.mobileFilterOptions}
        />

        {/* Main Content */}
        <div className="px-4 sm:px-6 lg:px-8 mt-6">
          {loading ? (
            renderLoadingSkeleton ? renderLoadingSkeleton() : defaultLoadingSkeleton()
          ) : hasNoItems ? (
            /* Empty state - no items at all */
            <Card className="p-12 text-center">
              {emptyState.icon}
              <h3 className="text-lg font-medium mb-2">
                {emptyState.noItemsTitle || emptyState.title}
              </h3>
              <p className="text-sm text-muted-foreground mb-4 max-w-sm mx-auto">
                {emptyState.noItemsDescription || emptyState.description}
              </p>
              {emptyState.showAddButton && onAdd && (
                <Button
                  onClick={onAdd}
                  className="min-h-[44px]"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  {emptyState.addButtonText || 'Add First Item'}
                </Button>
              )}
            </Card>
          ) : hasNoFilteredItems && isFiltered ? (
            /* Empty state - no results after filtering */
            <Card className="p-12 text-center">
              {emptyState.icon}
              <h3 className="text-lg font-medium mb-2">
                {emptyState.title}
              </h3>
              <p className="text-sm text-muted-foreground">
                {emptyState.description}
              </p>
            </Card>
          ) : (
            /* Render items */
            renderItems(filteredItems, viewMode?.current)
          )}
        </div>
      </div>

      {/* Floating Action Button */}
      {showFloatingActionButton && onAdd && (
        <div className="fixed bottom-20 lg:bottom-6 right-4 sm:right-6 lg:right-8 z-50">
          <Button
            size="lg"
            className="rounded-full shadow-lg h-14 w-14 p-0 bg-primary hover:bg-primary/90"
            onClick={onAdd}
            aria-label="Add new item"
          >
            <Plus className="h-6 w-6" />
          </Button>
        </div>
      )}

      {/* Modals */}
      {renderModals?.()}
    </div>
  )
}

import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Search, Filter, ChevronDown } from 'lucide-react'
import { FilterDropdown } from './FilterDropdown'

interface FilterOption {
  value: string
  label: string
  count?: number
}

interface CollectionHeaderProps {
  // Search
  searchTerm: string
  onSearchChange: (term: string) => void
  searchPlaceholder?: string

  // Primary Filter (optional)
  primaryFilter?: {
    options: FilterOption[]
    selectedValue: string | null
    onSelectValue: (value: string | null) => void
    placeholder?: string
    allItemsLabel?: string
    totalItems?: number
  }


  // Secondary controls (optional)
  secondaryControls?: React.ReactNode

  // Mobile filter options (if primaryFilter provided)
  mobileFilterOptions?: FilterOption[]

  // Styling
  className?: string
}

export function CollectionHeader({
  searchTerm,
  onSearchChange,
  searchPlaceholder = "Search...",
  primaryFilter,
  secondaryControls,
  mobileFilterOptions,
  className = ""
}: CollectionHeaderProps) {
  const [showMobileFilters, setShowMobileFilters] = useState(false)

  const selectedFilterOption = primaryFilter?.options.find(
    opt => opt.value === primaryFilter.selectedValue
  )

  return (
    <div className={`bg-white border-b border-border/40 sticky top-0 lg:top-0 z-40 ${className}`}>
      <div className="px-4 sm:px-6 lg:px-8 py-3">
        <div className="flex flex-col gap-3">
          {/* Search Bar */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              type="text"
              placeholder={searchPlaceholder}
              value={searchTerm}
              onChange={(e) => onSearchChange(e.target.value)}
              className="pl-10 min-h-[44px]"
            />
          </div>

          {/* Mobile Filter & Controls */}
          {(primaryFilter || secondaryControls) && (
            <div className="flex gap-2 sm:hidden">
              {primaryFilter && (
                <Button
                  variant="outline"
                  className="flex-1 justify-between min-h-[44px]"
                  onClick={() => setShowMobileFilters(!showMobileFilters)}
                >
                  <span className="flex items-center gap-2">
                    <Filter className="h-4 w-4" />
                    {selectedFilterOption?.label || primaryFilter.placeholder || 'All Items'}
                  </span>
                  <ChevronDown className={`h-4 w-4 transition-transform ${showMobileFilters ? 'rotate-180' : ''}`} />
                </Button>
              )}
              {/* Spacer to push secondary controls to the right when no primary filter */}
              {!primaryFilter && <div className="flex-1"></div>}
              {secondaryControls && (
                <div className="flex gap-2">
                  {secondaryControls}
                </div>
              )}
            </div>
          )}

          {/* Desktop Controls Row */}
          {(primaryFilter || secondaryControls) && (
            <div className="hidden sm:flex gap-2 items-center">
              {/* Primary Filter */}
              {primaryFilter && (
                <div className="w-48">
                  <FilterDropdown
                    options={primaryFilter.options}
                    selectedValue={primaryFilter.selectedValue}
                    onSelectValue={primaryFilter.onSelectValue}
                    placeholder={primaryFilter.placeholder}
                    allItemsLabel={primaryFilter.allItemsLabel}
                    totalItems={primaryFilter.totalItems}
                  />
                </div>
              )}

              {/* Spacer */}
              <div className="flex-1"></div>

              {/* Secondary Controls */}
              {secondaryControls && (
                <div className="flex gap-2 items-center">
                  {secondaryControls}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Mobile Filter Grid */}
        {primaryFilter && showMobileFilters && mobileFilterOptions && (
          <div className="mt-3 p-3 bg-muted/50 rounded-lg sm:hidden">
            <div className="grid grid-cols-2 gap-2">
              <Button
                variant={primaryFilter.selectedValue ? 'outline' : 'default'}
                size="sm"
                className="justify-start min-h-[44px]"
                onClick={() => {
                  primaryFilter.onSelectValue(null)
                  setShowMobileFilters(false)
                }}
              >
                {primaryFilter.allItemsLabel || 'All Items'}
              </Button>
              {mobileFilterOptions.map(option => (
                <Button
                  key={option.value}
                  variant={primaryFilter.selectedValue === option.value ? 'default' : 'outline'}
                  size="sm"
                  className="justify-start min-h-[44px]"
                  onClick={() => {
                    primaryFilter.onSelectValue(option.value === primaryFilter.selectedValue ? null : option.value)
                    setShowMobileFilters(false)
                  }}
                >
                  {option.label}
                </Button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

import { useState, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Package } from 'lucide-react'
import { useGearItems, useCreateGear, useUpdateGear, useDeleteGear } from '@/hooks/useGearData'
import { GearCard } from '@/components/gear/GearCard'
import { GearRow } from '@/components/gear/GearRow'
import { GearCompactRow } from '@/components/gear/GearCompactRow'
import { CollectionTable } from '@/components/shared/CollectionTable'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import { useViewMode } from '@/hooks/shared/useViewMode'
import { useWeightUnit } from '@/hooks/shared/useWeightUnit'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export function GearPage() {
  const { user } = useAuth()

  // Use React Query hooks for data fetching and mutations
  const { data: items = [], isLoading: loading } = useGearItems(user?.id)
  const createGearMutation = useCreateGear(user?.id)
  const updateGearMutation = useUpdateGear(user?.id)
  const deleteGearMutation = useDeleteGear(user?.id)

  const [viewMode, setViewMode] = useViewMode('gearViewMode')
  const [weightUnit, setWeightUnit] = useWeightUnit('gearWeightUnit')
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)


  // Filter items based on search and category with memoization
  const filteredItems = useMemo(() => {
    let filtered = items

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchLower) ||
        item.brand?.toLowerCase().includes(searchLower) ||
        item.model?.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower) ||
        item.notes?.toLowerCase().includes(searchLower) ||
        item.description?.toLowerCase().includes(searchLower)
      )
    }

    if (selectedCategory) {
      filtered = filtered.filter(item => item.category === selectedCategory)
    }

    return filtered
  }, [items, searchTerm, selectedCategory])



  // Calculate stats with memoization
  const { totalWeight, categories, categoryCounts } = useMemo(() => {
    const totalWeight = items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const categories = Array.from(new Set(items.map(item => item.category)))

    // Calculate category counts for dropdown
    const categoryCounts = items.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + 1
      return acc
    }, {} as Record<string, number>)

    return { totalWeight, categories, categoryCounts }
  }, [items])


  const handleAdd = useCallback(async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    if (!user) return

    try {
      await createGearMutation.mutateAsync(gear)
      setShowAddForm(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to add gear:', error)
    }
  }, [user, createGearMutation])

  const handleUpdate = useCallback(async (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    if (!user) return

    try {
      await updateGearMutation.mutateAsync({ id, updates })
      setEditingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to update gear:', error)
    }
  }, [user, updateGearMutation])

  const handleDelete = useCallback(async (id: string) => {
    if (!user) return

    try {
      await deleteGearMutation.mutateAsync(id)
      setDeletingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to delete gear:', error)
      setDeletingItem(null) // Still close the dialog
    }
  }, [user, deleteGearMutation])

  const renderItems = useCallback((items: GearItem[], currentViewMode?: string) => {
    const mode = (currentViewMode || viewMode) as ViewMode

    if (mode === 'comfortable') {
      return (
        <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
          {items.map(item => (
            <GearCard
              key={item.id}
              item={item}
              weightUnit={weightUnit}
              onEdit={() => setEditingItem(item)}
              onDelete={() => setDeletingItem(item)}
            />
          ))}
        </div>
      )
    }

    if (mode === 'default') {
      const columns = [
        {
          key: 'name',
          label: 'Item',
          sortable: true,
          sortValue: (item: GearItem) => item.name
        },
        {
          key: 'category',
          label: 'Category',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.category
        },
        {
          key: 'weight_grams',
          label: 'Weight',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.weight_grams
        },
        {
          key: 'quantity',
          label: 'Qty',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.quantity
        },
        {
          key: 'total',
          label: 'Total',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.weight_grams * item.quantity
        },
        { key: 'properties', label: 'Properties', hideOnMobile: true },
        { key: 'actions', label: '', className: 'text-right' }
      ]

      // Calculate totals for default view
      const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0)
      const totals = [
        null, // Category column - no total
        formatWeightWithUnit(totalWeight / totalQuantity || 0, weightUnit), // Avg weight per item
        totalQuantity, // Total quantity
        formatWeightWithUnit(totalWeight, weightUnit), // Total weight
        null // Properties column - no total
      ]

      return (
        <CollectionTable<GearItem>
          columns={columns}
          items={items}
          defaultSortField="name"
          showTotals={true}
          totals={totals}
          renderRow={(item) => (
            <GearRow
              key={item.id}
              item={item}
              weightUnit={weightUnit}
              onEdit={setEditingItem}

    className: 'text-right',
    sortValue: (item: GearItem) => item.weight_grams
  },
  {
    key: 'quantity',
    label: 'Qty',
    sortable: true,
    hideOnMobile: true,
    className: 'text-right',
    sortValue: (item: GearItem) => item.quantity
  },
  {
    key: 'total',
    label: 'Total',
    sortable: true,
    hideOnMobile: true,
    className: 'text-right font-medium',
    sortValue: (item: GearItem) => item.weight_grams * item.quantity
  },
  { key: 'properties', label: '', hideOnMobile: true },
  { key: 'actions', label: '', className: 'text-right' }
]

// Calculate totals for compact view
const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0)
const compactTotals = [
  null, // Category column - no total
  formatWeightWithUnit(totalWeight / totalQuantity || 0, weightUnit), // Avg weight per item
  totalQuantity, // Total quantity
  formatWeightWithUnit(totalWeight, weightUnit), // Total weight
  null // Properties column - no total
]

return (
  <CollectionTable<GearItem>
    columns={compactColumns}
    items={items}
    defaultSortField="name"
    showTotals={true}
    totals={compactTotals}
    renderRow={(item) => (
      <GearCompactRow
        key={item.id}
        item={item}
        weightUnit={weightUnit}
        onEdit={setEditingItem}
        onDelete={setDeletingItem}
        onDuplicate={handleAdd}
      />
    )}

