  )
}

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Button } from '@/components/ui/button'
import { Scale } from 'lucide-react'
import type { WeightUnit } from '@/types/database'

interface WeightUnitSelectorProps {
  value: WeightUnit
  onChange: (unit: WeightUnit) => void
}

const units: { value: WeightUnit; label: string; description: string }[] = [
  { value: 'g', label: 'Grams (g)', description: 'Metric - precise measurements' },
  { value: 'kg', label: 'Kilograms (kg)', description: 'Metric - heavier items' },
  { value: 'oz', label: 'Ounces (oz)', description: 'Imperial - lightweight gear' },
  { value: 'lb', label: 'Pounds (lb)', description: 'Imperial - heavier gear' },
]

export function WeightUnitSelector({ value, onChange }: WeightUnitSelectorProps) {
  const currentUnit = units.find(u => u.value === value)

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="default" className="gap-2 min-h-[44px]">
          <Scale className="h-4 w-4" />
          <span className="hidden sm:inline">{currentUnit?.value || 'g'}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        <DropdownMenuLabel>Weight Display Unit</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {units.map((unit) => (
          <DropdownMenuItem
            key={unit.value}
            onClick={() => onChange(unit.value)}
            className={`cursor-pointer ${value === unit.value ? 'bg-accent' : ''}`}
          >
            <div className="flex flex-col">
              <span className="font-medium">{unit.label}</span>
              <span className="text-xs text-muted-foreground">{unit.description}</span>
            </div>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import { Button } from '@/components/ui/button'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { LayoutGrid, LayoutList, TableProperties } from 'lucide-react'

export type ViewMode = 'comfortable' | 'default' | 'compact'

interface ViewModeSelectorProps {
  value: ViewMode
  onChange: (mode: ViewMode) => void
}

const VIEW_MODE_OPTIONS = [
  {
    value: 'comfortable' as const,
    label: 'Comfortable',
    icon: <LayoutGrid className="h-4 w-4" />,
    description: 'Card view with rich details and visuals'
  },
  {
    value: 'default' as const,
    label: 'Default',
    icon: <LayoutList className="h-4 w-4" />,
    description: 'Balanced view with essential information'
  },
  {
    value: 'compact' as const,
    label: 'Compact',
    icon: <TableProperties className="h-4 w-4" />,
    description: 'Minimal layout with maximum density'
  }
]

export function ViewModeSelector({ value, onChange }: ViewModeSelectorProps) {
  const currentMode = VIEW_MODE_OPTIONS.find(m => m.value === value) || VIEW_MODE_OPTIONS[0]

  return (
    <>
      {/* Mobile: Single cycling button */}
      <Button
        variant="outline"
        className="justify-center min-h-[44px] min-w-[44px] sm:hidden"
        onClick={() => {
          const mobileOptions = VIEW_MODE_OPTIONS.filter(opt => opt.value !== 'compact')
          const currentIndex = mobileOptions.findIndex(opt => opt.value === value)
          const nextIndex = (currentIndex + 1) % mobileOptions.length
          onChange(mobileOptions[nextIndex].value)
        }}
      >
        {currentMode.icon}
      </Button>

      {/* Desktop: Dropdown menu */}
      <div className="hidden sm:flex">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="gap-2 min-h-[44px]">
              {currentMode.icon}
              <span className="ml-2">{currentMode.label}</span>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-64">
            {VIEW_MODE_OPTIONS.map(mode => (
              <DropdownMenuItem
                key={mode.value}
                onClick={() => onChange(mode.value)}
                className="flex flex-col items-start py-3 cursor-pointer"
              >
                <div className="flex items-center space-x-2 mb-1">
                  {mode.icon}
                  <span className="font-medium">{mode.label}</span>
                  {mode.value === value && (
                    <span className="ml-auto text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">
                      Active
                    </span>
                  )}
                </div>
                <span className="text-xs text-muted-foreground">
                  {mode.description}
                </span>
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </>
  )
}

