import { useState, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Package } from 'lucide-react'
import { useGearItems, useCreateGear, useUpdateGear, useDeleteGear } from '@/hooks/useGearData'
import { GearCard } from '@/components/gear/GearCard'
import { GearRow } from '@/components/gear/GearRow'
import { GearCompactRow } from '@/components/gear/GearCompactRow'
import { CollectionTable } from '@/components/shared/CollectionTable'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import { useViewMode } from '@/hooks/shared/useViewMode'
import { useWeightUnit } from '@/hooks/shared/useWeightUnit'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export function GearPage() {
  const { user } = useAuth()

  // Use React Query hooks for data fetching and mutations
  const { data: items = [], isLoading: loading } = useGearItems(user?.id)
  const createGearMutation = useCreateGear(user?.id)
  const updateGearMutation = useUpdateGear(user?.id)
  const deleteGearMutation = useDeleteGear(user?.id)

  const [viewMode, setViewMode] = useViewMode('gearViewMode')
  const [weightUnit, setWeightUnit] = useWeightUnit('gearWeightUnit')
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)


  // Filter items based on search and category with memoization
  const filteredItems = useMemo(() => {
    let filtered = items

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchLower) ||
        item.brand?.toLowerCase().includes(searchLower) ||
        item.model?.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower) ||
        item.notes?.toLowerCase().includes(searchLower) ||
        item.description?.toLowerCase().includes(searchLower)
      )
    }

    if (selectedCategory) {
      filtered = filtered.filter(item => item.category === selectedCategory)
    }

    return filtered
  }, [items, searchTerm, selectedCategory])



  // Calculate stats with memoization
  const { totalWeight, categories, categoryCounts } = useMemo(() => {
    const totalWeight = items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
    const categories = Array.from(new Set(items.map(item => item.category)))

    // Calculate category counts for dropdown
    const categoryCounts = items.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + 1
      return acc
    }, {} as Record<string, number>)

    return { totalWeight, categories, categoryCounts }
  }, [items])


  const handleAdd = useCallback(async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    if (!user) return

    try {
      await createGearMutation.mutateAsync(gear)
      setShowAddForm(false)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to add gear:', error)
    }
  }, [user, createGearMutation])

  const handleUpdate = useCallback(async (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    if (!user) return

    try {
      await updateGearMutation.mutateAsync({ id, updates })
      setEditingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to update gear:', error)
    }
  }, [user, updateGearMutation])

  const handleDelete = useCallback(async (id: string) => {
    if (!user) return

    try {
      await deleteGearMutation.mutateAsync(id)
      setDeletingItem(null)
    } catch (error) {
      // Error is already handled by the mutation's onError
      console.error('Failed to delete gear:', error)
      setDeletingItem(null) // Still close the dialog
    }
  }, [user, deleteGearMutation])

  const renderItems = useCallback((items: GearItem[], currentViewMode?: string) => {
    const mode = (currentViewMode || viewMode) as ViewMode

    if (mode === 'comfortable') {
      return (
        <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
          {items.map(item => (
            <GearCard
              key={item.id}
              item={item}
              weightUnit={weightUnit}
              onEdit={() => setEditingItem(item)}
              onDelete={() => setDeletingItem(item)}
            />
          ))}
        </div>
      )
    }

    if (mode === 'default') {
      const columns = [
        {
          key: 'name',
          label: 'Item',
          sortable: true,
          sortValue: (item: GearItem) => item.name
        },
        {
          key: 'category',
          label: 'Category',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.category
        },
        {
          key: 'weight_grams',
          label: 'Weight',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.weight_grams
        },
        {
          key: 'quantity',
          label: 'Qty',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.quantity
        },
        {
          key: 'total',
          label: 'Total',
          sortable: true,
          hideOnMobile: true,
          className: 'text-right',
          sortValue: (item: GearItem) => item.weight_grams * item.quantity
        },
        { key: 'properties', label: 'Properties', hideOnMobile: true },
        { key: 'actions', label: '', className: 'text-right' }
      ]

      // Calculate totals for default view
      const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0)
      const totals = [
        null, // Category column - no total
        formatWeightWithUnit(totalWeight / totalQuantity || 0, weightUnit), // Avg weight per item
        totalQuantity, // Total quantity
        formatWeightWithUnit(totalWeight, weightUnit), // Total weight
        null // Properties column - no total
      ]

      return (
        <CollectionTable<GearItem>
          columns={columns}
          items={items}
          defaultSortField="name"
          showTotals={true}
          totals={totals}
          renderRow={(item) => (
            <GearRow
              key={item.id}
              item={item}
              weightUnit={weightUnit}
              onEdit={setEditingItem}
              onDelete={setDeletingItem}
              onDuplicate={handleAdd}
            />
          )}
        />
      )
    }

    // Compact view - use CollectionTable with compact columns
    const compactColumns = [
      {
        key: 'name',
        label: 'Item',
        sortable: true,
        sortValue: (item: GearItem) => item.name
      },
      {
        key: 'category',
        label: 'Category',
        sortable: true,
        hideOnMobile: true,
        className: 'text-right',
        sortValue: (item: GearItem) => item.category
      },
      {
        key: 'weight_grams',
        label: 'Weight',
        sortable: true,
        hideOnMobile: true,
        className: 'text-right',
        sortValue: (item: GearItem) => item.weight_grams
      },
      {
        key: 'quantity',
        label: 'Qty',
        sortable: true,
        hideOnMobile: true,
        className: 'text-right',
        sortValue: (item: GearItem) => item.quantity
      },
      {
        key: 'total',
        label: 'Total',
        sortable: true,
        hideOnMobile: true,
        className: 'text-right font-medium',
        sortValue: (item: GearItem) => item.weight_grams * item.quantity
      },
      { key: 'properties', label: '', hideOnMobile: true },
      { key: 'actions', label: '', className: 'text-right' }
    ]

    // Calculate totals for compact view
    const totalQuantity = items.reduce((sum, item) => sum + item.quantity, 0)
    const compactTotals = [
      null, // Category column - no total
      formatWeightWithUnit(totalWeight / totalQuantity || 0, weightUnit), // Avg weight per item
      totalQuantity, // Total quantity
      formatWeightWithUnit(totalWeight, weightUnit), // Total weight
      null // Properties column - no total
    ]

    return (
      <CollectionTable<GearItem>
        columns={compactColumns}
        items={items}
        defaultSortField="name"
        showTotals={true}
        totals={compactTotals}
        renderRow={(item) => (
          <GearCompactRow
            key={item.id}
            item={item}
            weightUnit={weightUnit}
            onEdit={setEditingItem}
            onDelete={setDeletingItem}
            onDuplicate={handleAdd}
          />
        )}
      />
    )
  }, [viewMode, weightUnit])

  const renderModals = useCallback(() => (
    <>
      {/* Add Gear Form Modal */}
      <AddGearFormWrapper
        isOpen={showAddForm}
        onAdd={handleAdd}
        onCancel={() => setShowAddForm(false)}
      />

      {/* Edit Gear Form Modal */}
      {editingItem && (
        <EditGearForm
          item={editingItem}
          onUpdate={handleUpdate}
          onCancel={() => setEditingItem(null)}
        />
      )}

      {/* Delete Confirmation Dialog */}
      {deletingItem && (
        <DeleteDialog
          item={deletingItem}
          onConfirm={() => handleDelete(deletingItem.id)}
          onCancel={() => setDeletingItem(null)}
        />
      )}
    </>
  ), [showAddForm, editingItem, deletingItem, handleAdd, handleUpdate, handleDelete])

  return (
    <CollectionPage<GearItem>
      items={items}
      filteredItems={filteredItems}
      loading={loading}
      title="Gear"
      subtitle="Track, categorize, and manage your outdoor gear collection."
      searchTerm={searchTerm}
      onSearchChange={setSearchTerm}
      searchPlaceholder="Search gear..."
      primaryFilter={{
        options: categories.map(category => ({
          value: category,
          label: category,
          count: categoryCounts[category]
        })),
        selectedValue: selectedCategory,
        onSelectValue: setSelectedCategory,
        placeholder: 'All Categories',
        allItemsLabel: 'All Categories',
        totalItems: items.length,
        mobileFilterOptions: categories.map(category => ({
          value: category,
          label: category,
          count: categoryCounts[category]
        }))
      }}
      viewMode={{
        current: viewMode,
        onChange: (mode: string) => setViewMode(mode as ViewMode),
        component: (
          <ViewModeSelector
            value={viewMode}
            onChange={setViewMode}
          />
        )
      }}
      secondaryControls={
        <div className="hidden sm:flex gap-2">
          <WeightUnitSelector value={weightUnit} onChange={setWeightUnit} />
        </div>
      }
      emptyState={{
        icon: <Package className="h-12 w-12 text-muted-foreground mx-auto mb-4" />,
        title: 'No gear found',
        description: 'Try adjusting your filters',
        noItemsTitle: 'No gear yet',
        noItemsDescription: 'Get started by adding your first item',
        showAddButton: true,
        addButtonText: 'Add First Item'
      }}
      renderItems={renderItems}
      onAdd={() => setShowAddForm(true)}
      renderModals={renderModals}
      showFloatingActionButton={true}
    />
  )
}

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Button } from '@/components/ui/button'
import { Scale } from 'lucide-react'
import type { WeightUnit } from '@/types/database'

interface WeightUnitSelectorProps {
  value: WeightUnit
  onChange: (unit: WeightUnit) => void
}

const units: { value: WeightUnit; label: string; description: string }[] = [
  { value: 'g', label: 'Grams (g)', description: 'Metric - precise measurements' },
  { value: 'kg', label: 'Kilograms (kg)', description: 'Metric - heavier items' },
  { value: 'oz', label: 'Ounces (oz)', description: 'Imperial - lightweight gear' },
  { value: 'lb', label: 'Pounds (lb)', description: 'Imperial - heavier gear' },
]

export function WeightUnitSelector({ value, onChange }: WeightUnitSelectorProps) {
  const currentUnit = units.find(u => u.value === value)

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="default" className="gap-2 min-h-[44px]">
          <Scale className="h-4 w-4" />
          <span className="hidden sm:inline">{currentUnit?.value || 'g'}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        <DropdownMenuLabel>Weight Display Unit</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {units.map((unit) => (
          <DropdownMenuItem
            key={unit.value}
            onClick={() => onChange(unit.value)}
            className={`cursor-pointer ${value === unit.value ? 'bg-accent' : ''}`}
          >
            <div className="flex flex-col">
              <span className="font-medium">{unit.label}</span>
              <span className="text-xs text-muted-foreground">{unit.description}</span>
            </div>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

