import { useState, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { ListDetailView } from '@/components/lists/ListDetailView'
import { ListCard } from '@/components/lists/ListCard'
import { ListRow } from '@/components/lists/ListRow'
import { ListCompactRow } from '@/components/lists/ListCompactRow'
import { CollectionTable } from '@/components/shared/CollectionTable'
import { CreateListFormWrapper } from '@/components/lists/CreateListFormWrapper'
import { EditListFormWrapper } from '@/components/lists/EditListFormWrapper'
import { DeleteListDialog } from '@/components/lists/DeleteListDialog'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { useViewMode } from '@/hooks/shared/useViewMode'
import { useWeightUnit } from '@/hooks/shared/useWeightUnit'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Package } from 'lucide-react'
import { useLists, useCreateList, useUpdateList, useDeleteList, useDuplicateList } from '@/hooks/useListData'
import { useGearItems } from '@/hooks/useGearData'
import type { List, WeightUnit, GearItem } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export function ListsPage() {
  const { user } = useAuth()
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingList, setEditingList] = useState<List | null>(null)
  const [deletingList, setDeletingList] = useState<List | null>(null)

  const [viewMode, setViewMode] = useViewMode('listsViewMode')
  const [weightUnit, setWeightUnit] = useWeightUnit('listsWeightUnit')

  // Data fetching
  const { data: lists = [], isLoading: listsLoading } = useLists(user?.id)
  const { data: gearItems = [], isLoading: gearLoading } = useGearItems(user?.id)

  // Mutations
  const createListMutation = useCreateList(user?.id)
  const updateListMutation = useUpdateList(user?.id)
  const deleteListMutation = useDeleteList(user?.id)
  const duplicateListMutation = useDuplicateList(user?.id)


  const handleCreateList = useCallback(async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await createListMutation.mutateAsync(data)
    setShowCreateForm(false)
  }, [createListMutation])

  const handleEditList = useCallback(async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await updateListMutation.mutateAsync({ id, updates })
    setEditingList(null)
  }, [updateListMutation])

  const handleDeleteList = useCallback(async (list: List) => {
    await deleteListMutation.mutateAsync(list.id)
    setDeletingList(null)
    // If we're viewing the deleted list, go back to list view
    if (selectedList?.id === list.id) {
      setSelectedList(null)
    }
  }, [deleteListMutation, selectedList])

  const handleDuplicateList = useCallback(async (list: List) => {
    const newName = `${list.name} (Copy)`
    await duplicateListMutation.mutateAsync({ listId: list.id, newName })
  }, [duplicateListMutation])

  const handleViewList = useCallback((list: List) => {
    setSelectedList(list)
  }, [])

  const handleBackToLists = () => {
    setSelectedList(null)
  }


  // Filter lists based on search term
  const filteredLists = useMemo(() => {
    if (!searchTerm) return lists

    const searchLower = searchTerm.toLowerCase()
    return lists.filter(list =>
      list.name.toLowerCase().includes(searchLower)
    )
  }, [lists, searchTerm])

  const isLoading = listsLoading || gearLoading

  const renderItems = useCallback((items: List[], currentViewMode?: string) => {
    const mode = currentViewMode || viewMode

    if (mode === 'comfortable') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {items.map((list) => (
            <ListCard
              key={list.id}
              list={list}
              gearItems={gearItems}
              weightUnit={weightUnit}
              onView={handleViewList}
              onEdit={setEditingList}
              onDelete={setDeletingList}
              onDuplicate={handleDuplicateList}
